/* Image-text synopsis viewer for the VLM transcription test case.
 * Data comes from results.js (window.RESULTS), generated by transcribe_test.py.
 * Facsimile pane uses the OpenSeadragon build vendored in the DoCTA repo (lib/),
 * so the viewer has real pan/zoom without any CDN dependency. */

const VARIANT_LABELS = {
  v1_baseline: "V1 Baseline",
  v2_structured: "V2 Strukturiert",
  v3_fewshot: "V3 Few-Shot",
  v4_split: "V4 Split",
  v5_repeat: "V5 Wiederholung",
  v6_enhanced: "V6 Kontrast",
};

const state = { item: null, tab: null };
let osd = null;

const $ = (sel) => document.querySelector(sel);

/* Escapes text and attribute values alike, so a quote in the data cannot break
 * out of an attribute. */
function esc(s) {
  return String(s).replace(/&/g, "&amp;").replace(/</g, "&lt;").replace(/>/g, "&gt;")
    .replace(/"/g, "&quot;");
}

/* One alternation over all uncertain words, applied in a single pass, so
 * inserted markup is never searched again. Longest first, or a longer word is
 * cut short by a shorter one contained in it. */
function markUncertain(text, words) {
  const html = esc(text);
  const keys = [...new Set((words || []).filter(Boolean).map((w) => esc(w)))]
    .sort((a, b) => b.length - a.length);
  if (!keys.length) return html;
  const re = new RegExp(keys.map((k) => k.replace(/[.*+?^${}()|[\]\\]/g, "\\$&")).join("|"), "g");
  return html.replace(re, (m) => `<mark class="uncertain">${m}</mark>`);
}

/** Render a transcript line, marking uncertain words. */
function renderLine(line) {
  const html = markUncertain(line.text || "", line.uncertain);
  const kind = (line.kind || "entry").toLowerCase();
  return `<li class="kind-${esc(kind)}">${html}</li>`;
}

function renderParsed(parsed) {
  let html = "";
  for (const page of parsed.pages || []) {
    html += `<div class="page-label">${esc(page.label || "Seite")}</div>`;
    if (page.empty || !(page.lines || []).length) {
      html += `<p class="empty-note">leer gemeldet</p>`;
      continue;
    }
    html += `<ol>${page.lines.map(renderLine).join("")}</ol>`;
  }
  if (parsed.notes) html += `<div class="notes">${esc(parsed.notes)}</div>`;
  return html;
}

function renderVariant(item, key) {
  const v = item.variants[key];
  if (!v) return `<p class="empty-note">kein Ergebnis vorhanden</p>`;
  if (v.parsed) return renderParsed(v.parsed);
  return `<ol>${v.lines.map((t) => renderLine({ text: t })).join("")}</ol>`;
}

function renderGT(item) {
  return `<ol>${item.gt.map((t) => renderLine({ text: t })).join("")}</ol>`;
}

function renderCompare(item, key) {
  const left = item.gt
    ? `<div><h3>Ground Truth (Transkribus)</h3>${renderGT(item)}</div>`
    : `<div><h3>${VARIANT_LABELS.v2_structured}</h3>${renderVariant(item, "v2_structured")}</div>`;
  const rightKey = item.gt ? key : (key === "v2_structured" ? "v5_repeat" : key);
  const right = `<div><h3>${VARIANT_LABELS[rightKey] || rightKey}</h3>${renderVariant(item, rightKey)}</div>`;
  return `<div class="compare">${left}${right}</div>`;
}

/** One row per variant: provenance, line count, GT metrics, stability vs. V2. */
function renderMetrics(item) {
  const s = window.RESULTS.summary[item.id] || {};
  const hasGT = Object.keys(s.cer || {}).length > 0;
  const bestFair = hasGT ? Math.min(...Object.values(s.cer).map((m) => m.fair)) : null;
  const head =
    `<tr><th>Variante</th><th>Zeilen</th><th>Dauer</th>` +
    (hasGT ? `<th>CER fair</th><th>CER strikt</th><th>Overlap GT</th>` : ``) +
    `<th>Overlap mit V2</th></tr>`;
  const rows = Object.keys(VARIANT_LABELS).filter((k) => item.variants[k]).map((k) => {
    const v = item.variants[k];
    const m = (s.cer || {})[k];
    const divKey = Object.keys(s.divergence || {}).find((p) => p.includes(k) && p.includes("v2_structured"));
    const div = divKey && k !== "v2_structured" ? s.divergence[divKey] : null;
    const lineCount = v.lines.length;
    return `<tr><th>${VARIANT_LABELS[k]}</th><td>${lineCount}</td><td>${v.duration_s}s</td>` +
      (hasGT
        ? (m
          ? `<td class="${m.fair === bestFair ? "best" : ""}">${(m.fair * 100).toFixed(1)}%</td>` +
            `<td>${(m.strict * 100).toFixed(1)}%</td><td>${(m.word_overlap * 100).toFixed(0)}%</td>`
          : `<td></td><td></td><td></td>`)
        : ``) +
      `<td>${div ? (div.word_overlap * 100).toFixed(0) + "%" : "–"}</td></tr>`;
  }).join("");
  const model = Object.values(item.variants)[0]?.model || "";
  $("#metrics").innerHTML =
    `<table>${head}${rows}</table>` +
    `<p class="metrics-note">${esc(model)} · CER gegen Transkribus-GT (fair = ohne Diakritika, Klammern, u/v) · ` +
    `Overlap mit V2 = geteiltes Vokabular mit dem Strukturiert-Lauf, niedrige Werte zeigen Instabilität</p>`;
}

function tabs(item) {
  const keys = Object.keys(item.variants);
  const list = keys.map((k) => ({ key: k, label: VARIANT_LABELS[k] || k, cls: "" }));
  if (item.gt) list.unshift({ key: "__gt", label: "Ground Truth", cls: "gt-tab" });
  list.push({ key: "__cmp", label: "Vergleich", cls: "" });
  return list;
}

function selectTab(key) {
  state.tab = key;
  const item = state.item;
  document.querySelectorAll("[role=tab]").forEach((el) => {
    const on = el.dataset.key === key;
    el.setAttribute("aria-selected", on ? "true" : "false");
    el.tabIndex = on ? 0 : -1;
  });
  let html;
  if (key === "__gt") html = renderGT(item);
  else if (key === "__cmp") html = renderCompare(item, "v2_structured");
  else html = renderVariant(item, key);
  $("#transcript").innerHTML = html;
}

function renderTabs(item) {
  const el = $("#tabs");
  el.innerHTML = "";
  for (const t of tabs(item)) {
    const b = document.createElement("button");
    b.type = "button";
    b.setAttribute("role", "tab");
    b.className = t.cls;
    b.dataset.key = t.key;
    b.textContent = t.label;
    b.addEventListener("click", () => selectTab(t.key));
    el.appendChild(b);
  }
}

/* Registered once on the tab strip, which outlives its buttons; registering it
 * per render stacked one handler per page switch. */
function initTabKeys() {
  const el = $("#tabs");
  el.addEventListener("keydown", (e) => {
    const all = [...el.querySelectorAll("[role=tab]")];
    const i = all.findIndex((x) => x.dataset.key === state.tab);
    let j = null;
    if (e.key === "ArrowRight") j = (i + 1) % all.length;
    if (e.key === "ArrowLeft") j = (i - 1 + all.length) % all.length;
    if (e.key === "Home") j = 0;
    if (e.key === "End") j = all.length - 1;
    if (j !== null) { e.preventDefault(); all[j].focus(); selectTab(all[j].dataset.key); }
  });
}

function itemIndex() {
  return window.RESULTS.items.findIndex((x) => x.id === state.item.id);
}

function selectItem(id) {
  const item = window.RESULTS.items.find((x) => x.id === id);
  state.item = item;
  $("#item-select").value = id;
  osd.open({ type: "image", url: `images/${item.id}.jpg` });
  renderMetrics(item);
  renderTabs(item);
  selectTab(item.gt ? "__gt" : tabs(item)[0].key);
}

function step(delta) {
  const items = window.RESULTS.items;
  const i = (itemIndex() + delta + items.length) % items.length;
  selectItem(items[i].id);
}

function init() {
  const data = window.RESULTS;
  $("#generated").textContent = `Stand ${data.generated}`;
  const sel = $("#item-select");
  for (const item of data.items) {
    const o = document.createElement("option");
    o.value = item.id;
    o.textContent = item.title;
    sel.appendChild(o);
  }
  sel.addEventListener("change", () => selectItem(sel.value));
  $("#prev").addEventListener("click", () => step(-1));
  $("#next").addEventListener("click", () => step(1));
  initTabKeys();

  osd = OpenSeadragon({
    id: "osd",
    showNavigationControl: false, // own buttons below; OSD button images are not vendored
    visibilityRatio: 1,
    minZoomLevel: 0.5,
    maxZoomPixelRatio: 2.5,
    gestureSettingsMouse: { clickToZoom: false, scrollToZoom: true },
  });
  $("#zoom-in").addEventListener("click", () => { osd.viewport.zoomBy(1.3); osd.viewport.applyConstraints(); });
  $("#zoom-out").addEventListener("click", () => { osd.viewport.zoomBy(1 / 1.3); osd.viewport.applyConstraints(); });
  $("#zoom-fit").addEventListener("click", () => osd.viewport.goHome());

  selectItem(data.items[0].id);
}

init();
